def get_nested_val(data, key_path, default=None):
    if not isinstance(data, dict):
        return default
    keys = key_path.split(".")
    curr = data
    for k in keys:
        if not isinstance(curr, dict) or k not in curr:
            return default
        curr = curr[k]
    return curr if curr is not None else default

