class TracedAccount:
    def __init__(self, acc_id, balance):
        self.id = acc_id
        self.balance = balance
        self.events = []
    @property
    def lock(self):
        acc = self
        class TracedLock:
            def __enter__(self):
                acc.events.append(f"acq_{acc.id}")
            def __exit__(self, *args):
                acc.events.append(f"rel_{acc.id}")
        return TracedLock()

def test_lock_ordering_invariant():
    log = []
    class SharedLockManager:
        def __init__(self):
            self.history = []
        def get_lock(self, acc_id):
            mgr = self
            class LockWrapper:
                def __enter__(self):
                    mgr.history.append(f"lock_{acc_id}")
                def __exit__(self, *args):
                    mgr.history.append(f"unlock_{acc_id}")
            return LockWrapper()

    mgr = SharedLockManager()
    class Account:
        def __init__(self, aid, bal):
            self.id = aid
            self.balance = bal
            self.lock = mgr.get_lock(aid)

    a2 = Account(2, 500)
    a1 = Account(1, 500)
    # Transfer from 2 to 1: Must acquire lock 1 before lock 2 to avoid AB-BA deadlock
    transfer_funds(a2, a1, 50)
    assert mgr.history[0] == "lock_1" and mgr.history[1] == "lock_2", f"Lock acquisition inverted! Got {mgr.history[:2]}"

