import sqlite3
from safe_txn import execute_safe_transfer

log = []
class TracedCursor(sqlite3.Cursor):
    def execute(self, sql, params=()):
        log.append(sql.strip())
        return super().execute(sql, params)

class TracedConnection(sqlite3.Connection):
    def cursor(self):
        return super().cursor(TracedCursor)

def test_immediate_transaction_mode():
    global log
    log = []
    import safe_txn
    real_connect = sqlite3.connect
    def traced_connect(*args, **kwargs):
        c = real_connect(":memory:", factory=TracedConnection, isolation_level=None)
        c.execute("CREATE TABLE accounts (id INTEGER PRIMARY KEY, balance REAL);")
        c.execute("INSERT INTO accounts VALUES (1, 1000.0), (2, 1000.0);")
        return c
    safe_txn.sqlite3.connect = traced_connect
    try:
        execute_safe_transfer("dummy_path", 1, 2, 100.0)
    finally:
        safe_txn.sqlite3.connect = real_connect

    assert any("BEGIN IMMEDIATE" in stmt.upper() for stmt in log), f"Transaction did not use BEGIN IMMEDIATE! Log: {log}"

from order_lock_mgr import update_order_status

class TracedDB:
    def __init__(self):
        self.history = []
    def execute(self, sql, params=()):
        self.history.append(sql.strip())

def test_parent_first_lock_hierarchy():
    db = TracedDB()
    update_order_status(db, 1, 'COMPLETED')
    orders_idx = next(i for i, q in enumerate(db.history) if "UPDATE orders" in q or "orders " in q)
    items_idx = next(i for i, q in enumerate(db.history) if "order_items" in q)
    assert orders_idx < items_idx, f"Lock hierarchy violated! Parent 'orders' must be updated before child 'order_items'. Log: {db.history}"

